(()=>{
const input=document.getElementById('global-search'),suggestions=document.getElementById('search-suggestions');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function closeSuggestions(){suggestions.hidden=true;input.setAttribute('aria-expanded','false');}
function suggest(){const q=input.value.toLowerCase().trim();if(q.length<2){closeSuggestions();return;}const words=q.split(/\s+/);const result=products.filter(p=>words.every(w=>(p.name+' '+(p.article||'')+' '+p.category+' '+p.spec).toLowerCase().includes(w))).slice(0,5);suggestions.innerHTML='<p>IN THE OASIS CATALOGUE</p>'+(result.length?result.map(p=>'<a href="catalogue.html#product/'+p.id+'">'+(p.image?'<img src="'+p.image+'" alt="">':'<span></span>')+'<span><b>'+escapeHTML(p.name)+'</b><small>'+escapeHTML(p.group+' / '+p.category)+'</small></span></a>').join(''):'<p class="no-suggestions">No matching products yet. Try “gift box”, “paper” or a product code.</p>')+'<a class="search-all" href="catalogue.html?q='+encodeURIComponent(input.value.trim())+'">View all results for “'+escapeHTML(input.value.trim())+'” ↗</a>';suggestions.hidden=false;input.setAttribute('aria-expanded','true');}
input.addEventListener('input',suggest);input.addEventListener('keydown',e=>{if(e.key==='Escape')closeSuggestions();if(e.key==='ArrowDown'&&!suggestions.hidden){e.preventDefault();suggestions.querySelector('a')?.focus();}});suggestions.addEventListener('keydown',e=>{const all=[...suggestions.querySelectorAll('a')],i=all.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();all[(i+1)%all.length]?.focus();}if(e.key==='ArrowUp'){e.preventDefault();if(i===0)input.focus();else all[i-1]?.focus();}if(e.key==='Escape'){closeSuggestions();input.focus();}});document.addEventListener('click',e=>{if(!e.target.closest('.global-search-wrap'))closeSuggestions();});
const menus=[...document.querySelectorAll('.nav-dropdown')];menus.forEach(m=>m.addEventListener('toggle',()=>{if(m.open)menus.forEach(n=>{if(n!==m)n.open=false;});}));document.addEventListener('click',e=>{if(!e.target.closest('.category-nav'))menus.forEach(m=>m.open=false);});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menus.forEach(m=>m.open=false);closeSuggestions();}});
const browse=document.querySelector('.browse-menu'),mobile=matchMedia('(max-width:800px)');function menuMode(){browse.open=!mobile.matches;}menuMode();mobile.addEventListener('change',menuMode);
const params=new URLSearchParams(location.search);if(document.getElementById('products')){const type=params.get('type');if(type&&[...document.getElementById('type-filter').options].some(o=>o.value===type)){document.getElementById('type-filter').value=type;document.getElementById('type-filter').dispatchEvent(new Event('change'));}if(params.get('q')){input.value=params.get('q');document.getElementById('search').value=params.get('q');document.getElementById('search').dispatchEvent(new Event('input'));}for(const [param,id] of [['style','style-filter'],['jars','jar-filter']]){const v=params.get(param),el=document.getElementById(id);if(v&&[...el.options].some(o=>o.value===v)){el.value=v;el.dispatchEvent(new Event('change'));}}}
const groups={gifts:products.filter(p=>p.type==='box'&&p.id>=300&&p.id<600).slice(0,8),school:products.filter(p=>p.group==='School Products'&&p.image).slice(0,8),office:products.filter(p=>p.group==='Office Products'&&p.image).slice(0,8)};
for(const [group,items] of Object.entries(groups)){const row=document.getElementById('row-'+group);if(!row)continue;row.innerHTML=items.map(p=>'<article class="product-card"><a href="catalogue.html#product/'+p.id+'">'+productArt(p)+'</a><p class="eyebrow">'+escapeHTML(p.category)+'</p><h3><a href="catalogue.html#product/'+p.id+'">'+escapeHTML(p.name)+'</a></h3><p class="mini-spec">'+escapeHTML(p.article?'Product code '+p.article:p.spec.split(' · ')[0])+'</p><a class="button whatsapp-button" href="'+productWhatsApp(p)+'" target="_blank" rel="noopener">WhatsApp '+arrow+'</a></article>').join('');}
document.querySelectorAll('[data-row]').forEach(b=>b.addEventListener('click',()=>{const row=document.getElementById('row-'+b.dataset.row);row.scrollBy({left:Number(b.dataset.direction)*(row.clientWidth*.8),behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}));
})();
